/* Shared code following stash; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts
   at 0x00295010 (was stash_00295010.c). */
#include "common.h"
#include "structs/misc.h"
#include "include_asm.h"
#include "asm_functions/executable.h"

extern StashBlock l00_stash_slots[];

// Starts a DMA transfer of size*16 bytes at offset*16 into a slot; -3 bad slot, -1 out of range.
int send_dma_to_stash_slot(int arg, unsigned int slot, int off, int size) {
    int req[4];
    int lim;
    if (slot >= 0x40)
        return -3;
    lim = l00_stash_slots[slot].qwc;
    if (lim == 0)
        return -3;
    if (lim < off + size)
        return -1;
    req[0] = arg;
    req[1] = (int)((char *)l00_stash_slots[slot].ram + off * 16);
    req[2] = size * 16;
    req[3] = 0;
    sce_sif_set_dma(req, IOP_STASH_FETCH);
    return 0;
}
/* The quadword count of stash slot SLOT, or -3 when there is no such slot. The catalogue splits
 * the `return -3` off as GetStashSlotSize_Tail (config/overlays/joined.tsv). */
int GetStashSlotSize(unsigned int slot) {
    if (slot >= 0x40)
        return -3;
    return l00_stash_slots[slot].qwc;
}
// Returns the constant -3.
int GetStashSlotSize_Tail(void) {
    return -3;
}
